require_once __DIR__ . '/includes/auth.php'; require_staff(); require_once __DIR__ . '/includes/mailer.php'; $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['form_action']??'';if($action==='save'){$residentId=(int)$_POST['resident_id'];$exists=$pdo->prepare('SELECT id FROM users WHERE username=? AND id<>?');$exists->execute([trim($_POST['username']),(int)($_POST['id']??0)]);if($exists->fetch()){flash('error','That username is already in use.');redirect('resident_accounts.php');}$resident=$pdo->prepare('SELECT full_name FROM residents WHERE id=?');$resident->execute([$residentId]);$resident=$resident->fetch();$email=trim($_POST['email']??'');$expiry=$_POST['account_expires_at']?:null;$id=(int)($_POST['id']??0);if(!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('error','Enter a valid resident email for OTP and notifications.');redirect('resident_accounts.php');}if($id){$sql='UPDATE users SET resident_id=?,full_name=?,email=?,username=?,account_expires_at=?,account_status=?'.(!empty($_POST['password'])?',password_hash=?':'').' WHERE id=?';$params=[$residentId,$resident['full_name'],$email,trim($_POST['username']),$expiry,$_POST['account_status']];if(!empty($_POST['password']))$params[]=password_hash($_POST['password'],PASSWORD_DEFAULT);$params[]=$id;$pdo->prepare($sql)->execute($params);flash('success','Resident portal account updated.');}else{$temporaryPassword=$_POST['password'];$pdo->prepare('INSERT INTO users (resident_id,full_name,email,username,password_hash,role,account_status,account_expires_at) VALUES (?,?,?,?,?,\'resident\',?,?)')->execute([$residentId,$resident['full_name'],$email,trim($_POST['username']),password_hash($temporaryPassword,PASSWORD_DEFAULT),$_POST['account_status'],$expiry]);send_notification($email,'Your Barangay resident portal account','<h2>Resident portal account created</h2><p>Your username is <strong>'.htmlspecialchars(trim($_POST['username']),ENT_QUOTES,'UTF-8').'</strong>.</p><p>The barangay office created your account. Use your password and the email OTP to sign in.</p>');flash('success','Resident portal account saved and notification email sent when Gmail SMTP is configured.');}redirect('resident_accounts.php');}if($action==='move_out'){$id=(int)$_POST['id'];$stmt=$pdo->prepare('SELECT resident_id FROM users WHERE id=?');$stmt->execute([$id]);$residentId=$stmt->fetchColumn();$pdo->prepare('UPDATE users SET account_status=\'expired\',account_expires_at=CURDATE() WHERE id=?')->execute([$id]);$pdo->prepare('UPDATE residents SET status=\'Moved out\',moved_out_at=NOW(),moved_to_barangay=? WHERE id=?')->execute([trim($_POST['moved_to_barangay']),$residentId]);flash('success','Resident account expired and move-out recorded.');redirect('resident_accounts.php');}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM users WHERE id=? AND role=\'resident\'');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$residents=$pdo->query("SELECT id,full_name,barangay_id,status FROM residents ORDER BY full_name")->fetchAll();$accounts=$pdo->query("SELECT u.*,r.barangay_id,r.status AS resident_status FROM users u LEFT JOIN residents r ON r.id=u.resident_id WHERE u.role='resident' ORDER BY u.created_at DESC")->fetchAll();$pageTitle='Resident accounts';$activePage='accounts';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Access / Resident portal</div><h1>Resident accounts</h1><p>Resident email is used for Gmail OTP sign-in and account notifications.</p></div><a class="primary-button" href="resident_accounts.php?action=new">＋ Create resident account</a></section><div class="priority-banner"><span class="priority-icon">!</span><div><strong>Account lifecycle rule</strong><small>Expired accounts cannot sign in. Their resident record remains available for retention and audit purposes.</small></div><a href="retention.php">Manage retention →</a></div><?php if(($_GET['action']??'')==='new'||$edit): ?><section class="panel form-panel"><div class="card-header"><div><div class="eyebrow">Resident portal</div><h2><?= $edit?'Edit resident account':'Create resident account' ?></h2></div><a class="text-button" href="resident_accounts.php">Close ×</a></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="save"><input type="hidden" name="id" value="<?= h($edit['id']??'') ?>"><label class="wide">Resident<select name="resident_id" required><?php foreach($residents as $resident): ?><option value="<?= h($resident['id']) ?>" <?= (($edit['resident_id']??'')==$resident['id'])?'selected':'' ?>><?= h($resident['full_name'].' · '.$resident['barangay_id'].' · '.$resident['status']) ?></option><?php endforeach; ?></select></label><label>Email for OTP<input type="email" name="email" required value="<?= h($edit['email']??'') ?>" placeholder="resident@gmail.com"></label><label>Username<input name="username" required value="<?= h($edit['username']??'') ?>"></label><label>Password<input type="password" name="password" <?= $edit?'':'required' ?> minlength="8" placeholder="<?= $edit?'Leave blank to keep current':'' ?>"></label><label>Account expires<input type="date" name="account_expires_at" value="<?= h($edit['account_expires_at']??date('Y-m-d',strtotime('+365 days'))) ?>"></label><label>Status<select name="account_status"><option value="active" <?= (($edit['account_status']??'active')==='active')?'selected':'' ?>>Active</option><option value="suspended" <?= (($edit['account_status']??'')==='suspended')?'selected':'' ?>>Suspended</option><option value="expired" <?= (($edit['account_status']??'')==='expired')?'selected':'' ?>>Expired</option></select></label><div class="form-actions"><a class="secondary-button" href="resident_accounts.php">Cancel</a><button class="primary-button">Save account</button></div></form></section><?php endif; ?><section class="panel table-panel"><div class="table-toolbar"><div><div class="eyebrow">Access registry</div><h2>Portal accounts</h2></div><span class="muted"><?= count($accounts) ?> resident accounts</span></div><div class="table-wrap"><table><thead><tr><th>Resident</th><th>Email / username</th><th>Expires</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($accounts as $account): ?><tr><td><strong><?= h($account['full_name']) ?></strong><small class="cell-subtext"><?= h($account['barangay_id']??'') ?> · <?= h($account['resident_status']??'') ?></small></td><td><?= h($account['email']) ?><small class="cell-subtext mono"><?= h($account['username']) ?></small></td><td class="muted"><?= $account['account_expires_at']?h(date('M d, Y',strtotime($account['account_expires_at']))):'No expiry' ?></td><td><span class="status-pill <?= h($account['account_status']) ?>"><i></i><?= h(ucfirst($account['account_status'])) ?></span></td><td class="actions"><a class="text-button" href="resident_accounts.php?edit=<?= h($account['id']) ?>">Edit</a><form method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="form_action" value="move_out"><input type="hidden" name="id" value="<?= h($account['id']) ?>"><input type="hidden" name="moved_to_barangay" value="Transferred / updated by administrator"><button class="danger-link" onclick="return confirm('Expire this account and mark the resident as moved out?')">Move out</button></form></td></tr><?php endforeach; ?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php'; ?>
